/// Complete vessel tree for rendering.
#[allow(dead_code)]
#[derive(Debug, Clone, Default)]
pub struct VesselTreeExt {
    /// All segments in the tree.
    pub segments: Vec<VesselSegmentExt>,
    /// Tree metadata.
    pub organ_name: String,
    /// Total blood volume in tree (mm³).
    pub total_volume: f64,
}
impl VesselTreeExt {
    /// Create empty vessel tree for given organ.
    pub fn new(organ_name: &str) -> Self {
        Self {
            organ_name: organ_name.to_string(),
            segments: Vec::new(),
            total_volume: 0.0,
        }
    }
    /// Add a segment and update total volume.
    pub fn add_segment(&mut self, seg: VesselSegmentExt) {
        self.total_volume += seg.volume();
        self.segments.push(seg);
    }
    /// Find all children of a segment.
    pub fn children_of(&self, parent_id: u32) -> Vec<&VesselSegmentExt> {
        self.segments
            .iter()
            .filter(|s| s.parent_id == parent_id && s.id != parent_id)
            .collect()
    }
    /// Total vessel length (mm).
    pub fn total_length(&self) -> f64 {
        self.segments.iter().map(|s| s.length()).sum()
    }
    /// Maximum generation depth.
    pub fn max_depth(&self) -> u32 {
        self.segments.iter().map(|s| s.id).max().unwrap_or(0)
    }
    /// Arteries only.
    pub fn arteries(&self) -> Vec<&VesselSegmentExt> {
        self.segments
            .iter()
            .filter(|s| s.vessel_type == VesselTypeExt::Artery)
            .collect()
    }
}
/// An orthogonal or oblique slice through a volume.
#[derive(Debug, Clone)]
pub struct SlicePlane {
    /// Slice orientation.
    pub orientation: SliceOrientation,
    /// Slice position (fractional coordinate along the normal axis, 0–1).
    pub position: f32,
    /// Oblique normal (used when orientation == Oblique).
    pub normal: [f32; 3],
    /// Output image width in pixels.
    pub width: usize,
    /// Output image height in pixels.
    pub height: usize,
}
impl SlicePlane {
    /// Create a new axial slice.
    pub fn axial(position: f32, width: usize, height: usize) -> Self {
        Self {
            orientation: SliceOrientation::Axial,
            position,
            normal: [0.0, 0.0, 1.0],
            width,
            height,
        }
    }
    /// Extract slice pixel values from a volume.
    pub fn extract(&self, volume: &VolumeData) -> Vec<f32> {
        let (w, h) = (self.width, self.height);
        let mut pixels = vec![0.0f32; w * h];
        for py in 0..h {
            for px in 0..w {
                let fx = px as f32 / (w - 1) as f32;
                let fy = py as f32 / (h - 1) as f32;
                let (sx, sy, sz) = match self.orientation {
                    SliceOrientation::Axial => (fx, fy, self.position),
                    SliceOrientation::Coronal => (fx, self.position, fy),
                    SliceOrientation::Sagittal => (self.position, fx, fy),
                    SliceOrientation::Oblique => (fx, fy, self.position),
                };
                pixels[py * w + px] = volume.sample(sx, sy, sz);
            }
        }
        pixels
    }
}
/// 3D radiation dose distribution.
#[allow(dead_code)]
#[derive(Debug, Clone)]
pub struct DoseDistribution {
    /// Voxel data (Gy).
    pub voxels: Vec<f32>,
    /// Volume dimensions \[nx, ny, nz\].
    pub dims: [usize; 3],
    /// Voxel size (mm).
    pub voxel_size: [f64; 3],
    /// Origin of dose grid (mm).
    pub origin: [f64; 3],
    /// Prescribed dose (Gy).
    pub prescribed_dose: f64,
    /// Dose unit.
    pub unit: DoseUnit,
}
impl DoseDistribution {
    /// Create a zero-initialized dose distribution.
    pub fn new(dims: [usize; 3], voxel_size: [f64; 3], origin: [f64; 3]) -> Self {
        let n = dims[0] * dims[1] * dims[2];
        Self {
            voxels: vec![0.0; n],
            dims,
            voxel_size,
            origin,
            prescribed_dose: 60.0,
            unit: DoseUnit::Gray,
        }
    }
    /// Voxel index from (ix, iy, iz).
    pub fn index(&self, ix: usize, iy: usize, iz: usize) -> usize {
        ix + self.dims[0] * (iy + self.dims[1] * iz)
    }
    /// Set dose at voxel.
    pub fn set(&mut self, ix: usize, iy: usize, iz: usize, dose: f32) {
        let idx = self.index(ix, iy, iz);
        if idx < self.voxels.len() {
            self.voxels[idx] = dose;
        }
    }
    /// Get dose at voxel.
    pub fn get(&self, ix: usize, iy: usize, iz: usize) -> f32 {
        let idx = self.index(ix, iy, iz);
        self.voxels.get(idx).copied().unwrap_or(0.0)
    }
    /// Sample dose at world position (mm) via trilinear interpolation.
    pub fn sample_at(&self, pos: [f64; 3]) -> f64 {
        let ix_f = (pos[0] - self.origin[0]) / self.voxel_size[0];
        let iy_f = (pos[1] - self.origin[1]) / self.voxel_size[1];
        let iz_f = (pos[2] - self.origin[2]) / self.voxel_size[2];
        let ix = ix_f as usize;
        let iy = iy_f as usize;
        let iz = iz_f as usize;
        let [nx, ny, nz] = self.dims;
        if ix >= nx || iy >= ny || iz >= nz {
            return 0.0;
        }
        let tx = ix_f - ix as f64;
        let ty = iy_f - iy as f64;
        let tz = iz_f - iz as f64;
        let ix1 = (ix + 1).min(nx - 1);
        let iy1 = (iy + 1).min(ny - 1);
        let iz1 = (iz + 1).min(nz - 1);
        let d000 = self.get(ix, iy, iz) as f64;
        let d100 = self.get(ix1, iy, iz) as f64;
        let d010 = self.get(ix, iy1, iz) as f64;
        let d110 = self.get(ix1, iy1, iz) as f64;
        let d001 = self.get(ix, iy, iz1) as f64;
        let d101 = self.get(ix1, iy, iz1) as f64;
        let d011 = self.get(ix, iy1, iz1) as f64;
        let d111 = self.get(ix1, iy1, iz1) as f64;
        let c00 = d000 * (1.0 - tx) + d100 * tx;
        let c10 = d010 * (1.0 - tx) + d110 * tx;
        let c01 = d001 * (1.0 - tx) + d101 * tx;
        let c11 = d011 * (1.0 - tx) + d111 * tx;
        let c0 = c00 * (1.0 - ty) + c10 * ty;
        let c1 = c01 * (1.0 - ty) + c11 * ty;
        c0 * (1.0 - tz) + c1 * tz
    }
    /// Maximum dose in the volume.
    pub fn max_dose(&self) -> f32 {
        self.voxels
            .iter()
            .cloned()
            .fold(f32::NEG_INFINITY, f32::max)
    }
    /// Mean dose over non-zero voxels.
    pub fn mean_dose(&self) -> f64 {
        let (sum, count) = self
            .voxels
            .iter()
            .filter(|&&v| v > 0.0)
            .fold((0.0_f64, 0_usize), |(s, c), &v| (s + v as f64, c + 1));
        if count > 0 { sum / count as f64 } else { 0.0 }
    }
    /// Dose-volume histogram (DVH) — fraction of volume receiving ≥ dose.
    ///
    /// Returns Vec of (dose_value, volume_fraction).
    pub fn dvh(&self, n_bins: usize) -> Vec<(f64, f64)> {
        if self.voxels.is_empty() || n_bins == 0 {
            return Vec::new();
        }
        let max_d = self.max_dose() as f64;
        let total = self.voxels.len() as f64;
        (0..n_bins)
            .map(|i| {
                let threshold = max_d * i as f64 / n_bins as f64;
                let fraction = self
                    .voxels
                    .iter()
                    .filter(|&&v| v as f64 >= threshold)
                    .count() as f64
                    / total;
                (threshold, fraction)
            })
            .collect()
    }
    /// V_D: volume fraction receiving at least `dose` Gy.
    pub fn volume_at_dose(&self, dose: f64) -> f64 {
        let total = self.voxels.len() as f64;
        if total == 0.0 {
            return 0.0;
        }
        self.voxels.iter().filter(|&&v| v as f64 >= dose).count() as f64 / total
    }
    /// D_V: minimum dose received by V% of the volume (quantile).
    pub fn dose_at_volume(&self, volume_fraction: f64) -> f64 {
        let mut sorted: Vec<f32> = self.voxels.clone();
        sorted.sort_by(|a, b| b.partial_cmp(a).unwrap_or(std::cmp::Ordering::Equal));
        let idx = ((1.0 - volume_fraction) * sorted.len() as f64) as usize;
        sorted.get(idx).map(|&v| v as f64).unwrap_or(0.0)
    }
}
