/// A piecewise-linear color transfer function mapping scalar values to RGBA.
#[derive(Debug, Clone)]
pub struct ColorTransferFunc {
    /// Sorted control points.
    pub points: Vec<TransferPoint>,
}
impl ColorTransferFunc {
    /// Create an empty transfer function.
    pub fn new() -> Self {
        Self { points: Vec::new() }
    }
    /// Add a control point. Points are kept sorted by scalar.
    pub fn add_point(&mut self, scalar: f32, color: Rgba) {
        self.points.push(TransferPoint { scalar, color });
        self.points.sort_by(|a, b| {
            a.scalar
                .partial_cmp(&b.scalar)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
    }
    /// Evaluate the transfer function at `scalar`.
    pub fn evaluate(&self, scalar: f32) -> Rgba {
        if self.points.is_empty() {
            return Rgba::transparent();
        }
        if scalar <= self.points[0].scalar {
            return self.points[0].color;
        }
        let last = &self.points[self.points.len() - 1];
        if scalar >= last.scalar {
            return last.color;
        }
        let idx = self.points.partition_point(|p| p.scalar <= scalar);
        if idx == 0 {
            return self.points[0].color;
        }
        let lo = &self.points[idx - 1];
        let hi = &self.points[idx];
        let t = (scalar - lo.scalar) / (hi.scalar - lo.scalar);
        Rgba::new(
            lerp(lo.color.r, hi.color.r, t),
            lerp(lo.color.g, hi.color.g, t),
            lerp(lo.color.b, hi.color.b, t),
            lerp(lo.color.a, hi.color.a, t),
        )
    }
    /// Bone tissue preset (white-yellow for cortical bone).
    pub fn bone_preset() -> Self {
        let mut tf = Self::new();
        tf.add_point(0.0, Rgba::new(0.0, 0.0, 0.0, 0.0));
        tf.add_point(0.3, Rgba::new(0.8, 0.6, 0.4, 0.3));
        tf.add_point(0.7, Rgba::new(0.9, 0.8, 0.7, 0.7));
        tf.add_point(1.0, Rgba::new(1.0, 1.0, 0.9, 1.0));
        tf
    }
    /// Soft tissue preset (reds for flesh).
    pub fn soft_tissue_preset() -> Self {
        let mut tf = Self::new();
        tf.add_point(0.0, Rgba::new(0.0, 0.0, 0.0, 0.0));
        tf.add_point(0.2, Rgba::new(0.7, 0.2, 0.2, 0.2));
        tf.add_point(0.6, Rgba::new(0.9, 0.4, 0.3, 0.6));
        tf.add_point(1.0, Rgba::new(1.0, 0.6, 0.5, 1.0));
        tf
    }
}
/// A 2D tumor contour on a slice image.
#[derive(Debug, Clone)]
pub struct TumorContour {
    /// Closed polygon vertices in pixel coordinates.
    pub vertices: Vec<[f32; 2]>,
    /// ROI name.
    pub name: String,
    /// Contour color.
    pub color: Rgba,
    /// Whether to fill the contour.
    pub filled: bool,
    /// Slice index on which this contour lives.
    pub slice_index: usize,
}
impl TumorContour {
    /// Create an empty tumor contour.
    pub fn new(name: &str, color: Rgba, slice_index: usize) -> Self {
        Self {
            vertices: Vec::new(),
            name: name.to_string(),
            color,
            filled: false,
            slice_index,
        }
    }
    /// Add a vertex to the contour.
    pub fn add_vertex(&mut self, v: [f32; 2]) {
        self.vertices.push(v);
    }
    /// Perimeter of the contour (pixels).
    pub fn perimeter(&self) -> f32 {
        let n = self.vertices.len();
        if n < 2 {
            return 0.0;
        }
        (0..n)
            .map(|i| {
                let a = self.vertices[i];
                let b = self.vertices[(i + 1) % n];
                let dx = b[0] - a[0];
                let dy = b[1] - a[1];
                (dx * dx + dy * dy).sqrt()
            })
            .sum()
    }
    /// Area enclosed by the contour using the shoelace formula (pixels²).
    pub fn area(&self) -> f32 {
        let n = self.vertices.len();
        if n < 3 {
            return 0.0;
        }
        let sum: f32 = (0..n)
            .map(|i| {
                let a = self.vertices[i];
                let b = self.vertices[(i + 1) % n];
                a[0] * b[1] - b[0] * a[1]
            })
            .sum();
        sum.abs() * 0.5
    }
    /// Centroid of the contour.
    pub fn centroid(&self) -> [f32; 2] {
        if self.vertices.is_empty() {
            return [0.0; 2];
        }
        let n = self.vertices.len() as f32;
        let sx: f32 = self.vertices.iter().map(|v| v[0]).sum::<f32>() / n;
        let sy: f32 = self.vertices.iter().map(|v| v[1]).sum::<f32>() / n;
        [sx, sy]
    }
    /// Check if a point is inside the contour (ray-casting algorithm).
    pub fn contains(&self, point: [f32; 2]) -> bool {
        let n = self.vertices.len();
        if n < 3 {
            return false;
        }
        let mut inside = false;
        let (px, py) = (point[0], point[1]);
        let mut j = n - 1;
        for i in 0..n {
            let (xi, yi) = (self.vertices[i][0], self.vertices[i][1]);
            let (xj, yj) = (self.vertices[j][0], self.vertices[j][1]);
            if ((yi > py) != (yj > py)) && (px < (xj - xi) * (py - yi) / (yj - yi) + xi) {
                inside = !inside;
            }
            j = i;
        }
        inside
    }
}
