/// A segment of a vessel tree (centerline + radius).
#[derive(Debug, Clone)]
pub struct VesselSegment {
    /// Start centre point.
    pub start: [f32; 3],
    /// End centre point.
    pub end: [f32; 3],
    /// Radius at start.
    pub radius_start: f32,
    /// Radius at end.
    pub radius_end: f32,
    /// Child segment indices.
    pub children: Vec<usize>,
}
impl VesselSegment {
    /// Create a new vessel segment.
    pub fn new(start: [f32; 3], end: [f32; 3], radius_start: f32, radius_end: f32) -> Self {
        Self {
            start,
            end,
            radius_start,
            radius_end,
            children: Vec::new(),
        }
    }
    /// Length of the segment.
    pub fn length(&self) -> f32 {
        let d = [
            self.end[0] - self.start[0],
            self.end[1] - self.start[1],
            self.end[2] - self.start[2],
        ];
        norm3f(d)
    }
}
/// Surgical incision path in 3D space.
#[allow(dead_code)]
#[derive(Debug, Clone)]
pub struct IncisionPath {
    /// Sequence of 3D points defining the incision line.
    pub points: Vec<[f64; 3]>,
    /// Incision depth at each point (m).
    pub depths: Vec<f64>,
    /// Tissue layer indices at each point.
    pub tissue_layers: Vec<u32>,
}
impl IncisionPath {
    /// Create an empty incision path.
    pub fn new() -> Self {
        Self {
            points: Vec::new(),
            depths: Vec::new(),
            tissue_layers: Vec::new(),
        }
    }
    /// Add a point to the incision path.
    pub fn add_point(&mut self, p: [f64; 3], depth: f64, layer: u32) {
        self.points.push(p);
        self.depths.push(depth);
        self.tissue_layers.push(layer);
    }
    /// Total length of the incision path.
    pub fn total_length(&self) -> f64 {
        let mut len = 0.0;
        for i in 1..self.points.len() {
            let a = self.points[i - 1];
            let b = self.points[i];
            let dx = b[0] - a[0];
            let dy = b[1] - a[1];
            let dz = b[2] - a[2];
            len += (dx * dx + dy * dy + dz * dz).sqrt();
        }
        len
    }
    /// Average depth of incision.
    pub fn average_depth(&self) -> f64 {
        if self.depths.is_empty() {
            return 0.0;
        }
        self.depths.iter().sum::<f64>() / self.depths.len() as f64
    }
}
/// Surgical planning session with collision checking.
#[allow(dead_code)]
#[derive(Debug, Clone, Default)]
pub struct SurgicalPlan {
    /// Trocar ports.
    pub ports: Vec<TrocarPort>,
    /// Incision paths.
    pub incisions: Vec<IncisionPath>,
    /// Surgical target regions.
    pub targets: Vec<[f64; 3]>,
    /// Safety margin from critical structures (mm).
    pub safety_margin: f64,
    /// Planning quality score \[0..1\].
    pub quality_score: f64,
}
impl SurgicalPlan {
    /// Create with given safety margin.
    pub fn new(safety_margin: f64) -> Self {
        Self {
            safety_margin,
            ..Default::default()
        }
    }
    /// Add a trocar port.
    pub fn add_port(&mut self, port: TrocarPort) {
        self.ports.push(port);
    }
    /// Check if two ports are sufficiently separated.
    pub fn ports_collision_free(&self) -> bool {
        let n = self.ports.len();
        for i in 0..n {
            for j in (i + 1)..n {
                let a = self.ports[i].position;
                let b = self.ports[j].position;
                let dx = a[0] - b[0];
                let dy = a[1] - b[1];
                let dz = a[2] - b[2];
                let dist = (dx * dx + dy * dy + dz * dz).sqrt();
                let min_sep =
                    (self.ports[i].diameter + self.ports[j].diameter) / 2.0 + self.safety_margin;
                if dist < min_sep {
                    return false;
                }
            }
        }
        true
    }
    /// Estimate total incision length.
    pub fn total_incision_length(&self) -> f64 {
        self.incisions.iter().map(|inc| inc.total_length()).sum()
    }
}
/// MRI relaxation parameters for a tissue type.
#[derive(Debug, Clone, Copy)]
pub struct MriTissue {
    /// T1 longitudinal relaxation time (ms).
    pub t1: f32,
    /// T2 transverse relaxation time (ms).
    pub t2: f32,
    /// Proton density (relative).
    pub pd: f32,
}
impl MriTissue {
    /// Create a tissue with given T1/T2/PD.
    pub fn new(t1: f32, t2: f32, pd: f32) -> Self {
        Self { t1, t2, pd }
    }
    /// White matter approximate values.
    pub fn white_matter() -> Self {
        Self::new(790.0, 90.0, 0.65)
    }
    /// Grey matter approximate values.
    pub fn grey_matter() -> Self {
        Self::new(950.0, 100.0, 0.80)
    }
    /// CSF approximate values.
    pub fn csf() -> Self {
        Self::new(4000.0, 2000.0, 1.0)
    }
    /// T1-weighted signal: S = PD · (1 - exp(-TR/T1)) · exp(-TE/T2).
    pub fn t1_weighted_signal(&self, tr: f32, te: f32) -> f32 {
        self.pd * (1.0 - (-tr / self.t1).exp()) * (-te / self.t2).exp()
    }
    /// T2-weighted signal: S = PD · exp(-TE/T2)  (long TR assumed).
    pub fn t2_weighted_signal(&self, te: f32) -> f32 {
        self.pd * (-te / self.t2).exp()
    }
    /// Inversion recovery signal at time TI after 180° pulse.
    pub fn inversion_recovery_signal(&self, ti: f32, tr: f32, te: f32) -> f32 {
        let mz = self.pd * (1.0 - 2.0 * (-ti / self.t1).exp() + (-tr / self.t1).exp());
        mz.abs() * (-te / self.t2).exp()
    }
}
