/// A single isodose contour level.
#[derive(Debug, Clone)]
pub struct IsodoseContour {
    /// Dose level (Gy or % of prescribed).
    pub dose_level: f32,
    /// Display color for this contour.
    pub color: Rgba,
    /// Line segments forming the contour (pairs of 2D points in mm).
    pub segments: Vec<([f32; 2], [f32; 2])>,
}
impl IsodoseContour {
    /// Create an empty isodose contour.
    pub fn new(dose_level: f32, color: Rgba) -> Self {
        Self {
            dose_level,
            color,
            segments: Vec::new(),
        }
    }
    /// Add a line segment.
    pub fn add_segment(&mut self, start: [f32; 2], end: [f32; 2]) {
        self.segments.push((start, end));
    }
    /// Total contour length (mm).
    pub fn total_length(&self) -> f32 {
        self.segments
            .iter()
            .map(|(a, b)| {
                let dx = b[0] - a[0];
                let dy = b[1] - a[1];
                (dx * dx + dy * dy).sqrt()
            })
            .sum()
    }
}
